// HasTermSet applies the HasEdge predicate on the "term_set" edge.
func HasTermSet() predicate.Term {
	return predicate.Term(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, TermSetTable, TermSetColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasTermSetWith applies the HasEdge predicate on the "term_set" edge with a given conditions (other predicates).
func HasTermSetWith(preds ...predicate.TermSet) predicate.Term {
	return predicate.Term(func(s *sql.Selector) {
		step := newTermSetStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

